begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/costing-salon.inc
create function pg_temp.report(q jsonb default '{}'::jsonb) returns jsonb language sql volatile as $$
 select public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',q);
$$;
create function pg_temp.metric(n text,q jsonb default '{}'::jsonb) returns text language sql volatile as $$
 select m->>'value' from jsonb_array_elements(pg_temp.report(q)->'data'->'metrics') m where m->>'name'=n;
$$;
create function pg_temp.report_op(q jsonb) returns jsonb language sql volatile as $$
 select public.reporting_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',q,gen_random_uuid());
$$;
set local role authenticated;
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000201','PERCENT_NET_OF_TAX',1000)#>>'{data,status}','SAVED','real commission policy');
select ok(pg_temp.costing(jsonb_build_object('type','ASSIGN','mutation_id',gen_random_uuid(),'id',gen_random_uuid(),'staff_user_id','b4000000-0000-4000-8000-000000000021','policy_id','c5000000-0000-4000-8000-000000000201','scope','DEFAULT_SERVICE','service_id',null,'category',null,'effective_from',statement_timestamp(),'effective_until',null,'reason','Report performer test')) ? 'data','authoritative performed_by assignment');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000811',1,'ARRIVED');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000811',2,'IN_SERVICE');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000811',3,'COMPLETED');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000812',1,'CANCELLED');
select is(pg_temp.metric('completed_visits','{"period":"CUSTOM","from":"2026-10-01","until":"2026-10-31"}'),'1','COMPLETED is one visit');
select is(pg_temp.metric('cancelled','{"period":"CUSTOM","from":"2026-10-01","until":"2026-10-31"}'),'1','cancelled cohort exact');
select is(pg_temp.metric('no_show','{"period":"CUSTOM","from":"2026-10-01","until":"2026-10-31"}'),'0','no-show not invented');
select is(pg_temp.metric('available_staff_minutes'),null::text,'unknown eligible capacity is not invented');
select is(pg_temp.metric('utilization_bps'),null::text,'utilization unavailable without a validated denominator');
select ok(pg_temp.charge_appointment('c5000000-0000-4000-8000-000000000301','e5000000-0000-4000-8000-000000000811') ? 'data','real charge posted');
select is(pg_temp.metric('recognized_net_revenue'),'100000','net-of-tax recognition exact');
select is(pg_temp.metric('unknown_transactions'),'1','missing cost explicitly UNKNOWN');
select is(pg_temp.metric('known_count_coverage_bps'),'0','unknown transaction count denominator');
select is(pg_temp.metric('known_revenue_coverage_bps'),'0','unknown revenue denominator');
select is(pg_temp.metric('contribution_after_commission'),null::text,'unknown cost never becomes zero contribution');
select is(pg_temp.metric('net_accrued_commission'),'10000','performer commission exact, not cashier attribution');
select ok(pg_temp.finance_payment('DEPOSIT','20000','c5000000-0000-4000-8000-000000000302') ? 'data','deposit credit posted');
select is(pg_temp.metric('recognized_net_revenue'),'100000','deposit is not revenue');
select ok(pg_temp.costing(jsonb_build_object('type','DECLARE_NO_STOCK','mutation_id',gen_random_uuid(),'charge_id','c5000000-0000-4000-8000-000000000301','reason','Measured zero product use')) ? 'data','reviewed zero source');
select is(pg_temp.metric('known_transactions'),'1','measured zero is KNOWN');
select is(pg_temp.metric('known_count_coverage_bps'),'10000','complete count coverage');
select is(pg_temp.metric('known_revenue_coverage_bps'),'10000','complete revenue coverage');
select is(pg_temp.metric('known_direct_product_cost'),'0','known zero exact');
select is(pg_temp.metric('contribution_before_commission'),'100000','before commission exact');
select is(pg_temp.metric('contribution_after_commission'),'90000','after commission exact');
select ok(pg_temp.finance_payment('PAYMENT','120000','c5000000-0000-4000-8000-000000000303','[{"charge_id":"c5000000-0000-4000-8000-000000000301","amount_minor":"120000"}]') ? 'data','payment allocated');
select is(pg_temp.metric('recognized_net_revenue'),'100000','collection is not a second revenue event');
select ok(pg_temp.finance(jsonb_build_object('type','REFUND','mutation_id',gen_random_uuid(),'id','c5000000-0000-4000-8000-000000000304','original_payment_id','c5000000-0000-4000-8000-000000000303','amount_minor','60000','occurred_at',statement_timestamp(),'reason','Half actual refund')) ? 'data','actual refund');
-- These fixture commands share one transaction; execute the real deferred source
-- trigger before simulating the next committed HTTP report request.
set constraints profitability_refund_posted immediate;
select is(pg_temp.metric('recognized_net_revenue'),'50000','refund reflected once');
select is(pg_temp.metric('refunds_net'),'50000','refund numerator exact');
select is(pg_temp.metric('net_accrued_commission'),'5000','refund commission adjustment exact');
select is(pg_temp.metric('contribution_after_commission'),'45000','net contribution after refund');
select ok(pg_temp.report_op('{"type":"REBUILD"}') ? 'data','scoped rebuild succeeds');
select is(pg_temp.metric('recognized_net_revenue'),'50000','rebuild deterministic revenue');
select is(pg_temp.metric('contribution_after_commission'),'45000','rebuild deterministic contribution');
select is(pg_temp.report('{"period":"CUSTOM","from":"2026-01-01","until":"2026-01-01"}')#>>'{data,period,start}','2025-12-31T21:00:00+00:00','salon midnight converted explicitly');
select is(pg_temp.report('{"period":"CUSTOM","from":"2026-01-01","until":"2026-01-01"}')#>>'{data,period,end}','2026-01-01T21:00:00+00:00','custom last day inclusive, interval end exclusive');
select is(pg_temp.report('{"period":"CUSTOM","from":"2026-01-01","until":"2026-01-01"}')#>>'{data,period,previous_first_date}','2025-12-31','equivalent calendar comparison');
select is(pg_temp.metric('known_revenue_coverage_bps','{"period":"CUSTOM","from":"2026-01-01","until":"2026-01-01"}'),null::text,'zero denominator unavailable');
select is(pg_temp.report('{"period":"CUSTOM","from":"2026-01-01","until":"2026-04-01"}')->>'code','VALIDATION_FAILED','custom interval bounded');
select is(pg_temp.report('{"sql":"select secret"}')->>'code','VALIDATION_FAILED','no arbitrary query language');
select is(pg_temp.report_op('{"type":"SETTINGS","expected_version":0,"coverage_warning_bps":9000,"cancellation_warning_bps":1000}')#>>'{data,version}','1','explicit operational thresholds');
select is(pg_temp.report_op('{"type":"SETTINGS","expected_version":0,"coverage_warning_bps":8000,"cancellation_warning_bps":1000}')->>'code','REPORT_CONFLICT','conditional settings version');
reset role;
-- Use the separate empty organization for setup-metadata drift; the completed
-- source organization is already protected by the existing Finance/cost guard.
update public.organizations set base_currency='USD' where id='b4000000-0000-4000-8000-000000000002';
insert into public.finance_settings(organization_id,currency,exponent,version,updated_by,updated_at)
 values('b4000000-0000-4000-8000-000000000002','TRY',2,1,'b4000000-0000-4000-8000-000000000022',statement_timestamp());
set local role authenticated;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);
select is(public.reporting_snapshot('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000012','{}')#>>'{data,currency}','TRY','registered Finance currency remains monetary authority for a separately initialized organization');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
reset role;
set local role authenticated;
select ok(pg_temp.move('OPENING','c5000000-0000-4000-8000-000000000101',10) ? 'data','measured threshold stock opening');
select is(pg_temp.report('{"kind":"STOCK","domain":"STOCK_ITEM","source_id":"c5000000-0000-4000-8000-000000000101"}')#>>'{data,items,0,status}','LOW','report uses source LOW semantics at threshold equality');
select ok(pg_temp.report_op('{"type":"EXPORT","request":{"kind":"FINANCE"}}') ? 'data','bounded authorized export');
reset role;
select is(extract(epoch from ((app_private.report_period('Europe/Berlin','{"period":"CUSTOM","from":"2026-03-29","until":"2026-03-29"}')->>'end')::timestamptz-(app_private.report_period('Europe/Berlin','{"period":"CUSTOM","from":"2026-03-29","until":"2026-03-29"}')->>'start')::timestamptz)),82800::numeric,'DST spring salon day is 23 hours');
select throws_ok($$update public.organizations set base_currency='USD' where id='b4000000-0000-4000-8000-000000000001'$$,'23514','CURRENCY_LOCKED','existing immutable costing currency guard remains enforced');
select is(extract(epoch from ((app_private.report_period('Europe/Berlin','{"period":"CUSTOM","from":"2026-10-25","until":"2026-10-25"}')->>'end')::timestamptz-(app_private.report_period('Europe/Berlin','{"period":"CUSTOM","from":"2026-10-25","until":"2026-10-25"}')->>'start')::timestamptz)),90000::numeric,'DST autumn salon day is 25 hours');
select is((select count(*) from public.audit_events where action='reporting.rebuild'),1::bigint,'rebuild audited once');
select is((select count(*) from public.audit_events where action='reporting.export'),1::bigint,'sensitive export audited');
select is((select metadata#>>'{new_settings,coverage_warning_bps}' from public.audit_events where action='reporting.settings'),'9000','configuration audit preserves threshold provenance');
select ok(not has_table_privilege('authenticated','app_private.report_facts','select'),'private report rows not directly readable');
select ok(not has_table_privilege('authenticated','app_private.report_facts','insert'),'projection direct mutation denied');
select ok(not has_table_privilege('authenticated','app_private.report_invalidations','update'),'queue direct mutation denied');
select ok((select relrowsecurity from pg_class where oid='app_private.report_facts'::regclass),'projection RLS enabled');
select ok(not has_function_privilege('anon','public.reporting_snapshot(uuid,uuid,jsonb)','execute'),'anonymous report RPC denied');
-- Reuse existing synthetic fixture identities; do not collide with auth PKs.
update public.salon_memberships set role_code='colorist' where id='b4000000-0000-4000-8000-000000000113';
set local role authenticated;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000024',true);
select ok(not (public.reporting_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{}')->'data'->'allowed_domains' ? 'COMMISSION'),'reception has no colleague commission');
select ok(not (public.reporting_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{}')->'data'->'allowed_domains' ? 'COST'),'reception has no acquisition/direct costs');
select ok(not (public.reporting_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{}')->'data'->'allowed_domains' ? 'LIVE'),'reception has no restricted technical details');
select is(public.reporting_snapshot('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"kind":"TECHNICAL"}')->>'code','FORBIDDEN','restricted report denied server side');
select ok(public.reporting_operation('b4000000-0000-4000-8000-000000000114','b4000000-0000-4000-8000-000000000011','{"type":"EXPORT","request":{}}',gen_random_uuid()) ? 'code','export permission enforced');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000023',true);
select is(public.reporting_snapshot('b4000000-0000-4000-8000-000000000113','b4000000-0000-4000-8000-000000000011','{}')#>>'{data,self_only}','true','colorist self mode');
select is(jsonb_array_length(public.reporting_snapshot('b4000000-0000-4000-8000-000000000113','b4000000-0000-4000-8000-000000000011','{}')->'data'->'items'),0,'colleague source records excluded');
select is(public.reporting_snapshot('b4000000-0000-4000-8000-000000000113','b4000000-0000-4000-8000-000000000011','{"staff_user_id":"b4000000-0000-4000-8000-000000000021"}')->>'code','FORBIDDEN','forged colleague filter denied');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
select ok(public.reporting_snapshot('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000012','{}') ? 'code','cross-org denied');
select ok(public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000012','{}') ? 'code','cross-location denied');
reset role;
insert into public.locations(id,organization_id,name,timezone) values('b4000000-0000-4000-8000-000000000013','b4000000-0000-4000-8000-000000000001','Second scoped branch','UTC');
set local role authenticated;
select ok(public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000013','{}') ? 'code','location-limited owner cannot widen scope');
reset role;
update public.salon_memberships set location_id=null where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select is(public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000013','{}')#>>'{data,location_id}','b4000000-0000-4000-8000-000000000013','organization-wide owner still selects one authorized branch');
select is((select m->>'value' from jsonb_array_elements(public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000013','{}')->'data'->'metrics')m where m->>'name'='recognized_net_revenue'),'0','authorized second branch does not inherit first-branch revenue');
select is(jsonb_array_length(public.reporting_snapshot('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000013','{"kind":"CLIENTS"}')->'data'->'items'),1,'new branch bootstraps existing canonical CRM family without duplicating identity');
reset role;
update public.salon_memberships set status='revoked',revoked_at=statement_timestamp() where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select ok(pg_temp.report() ? 'code','revoked membership report denied');
select * from finish();
rollback;
